    {
        ["browser.navigate"] = new("browser.navigate", BrowserFeature.Navigate, "core", ToolEffect.ReadOnly, """{"type":"object","additionalProperties":false,"properties":{"operation":{"type":"string","enum":["goto","back","forward","reload"]},"url":{"type":"string","maxLength":2048}},"required":[]}"""),
        ["browser.snapshot"] = new("browser.snapshot", BrowserFeature.Snapshot, "core", ToolEffect.ReadOnly, """{"type":"object","additionalProperties":false,"properties":{"targetRef":{"type":"string","maxLength":128},"depth":{"type":"integer","minimum":1,"maximum":32},"boxes":{"type":"boolean"}},"required":[]}"""),
